package mz.bam.seeky.android;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class StudioAudioTest {
 static int checks;static void ok(boolean b,String s){if(!b)throw new AssertionError(s);checks++;System.out.println("PASS "+s);}
 public static void main(String[] args)throws Exception{Path root=Files.createTempDirectory("seeky-studio-audio-");File a=root.resolve("a.wav").toFile(),b=root.resolve("b.wav").toFile(),partial=root.resolve("partial.wav").toFile();WaveJoinerTest.wav(a,24000,1,16,new byte[]{1,0});WaveJoinerTest.wav(b,24000,1,16,new byte[]{2,0});try(CheckpointWave wave=new CheckpointWave(partial,0,0,0,0,0)){wave.append(a,()->false);wave.checkpoint();wave.append(b,()->false);}try(CheckpointWave wave=new CheckpointWave(partial,2,1,1,24000,16)){ok(partial.length()==46,"restart truncates uncommitted PCM tail");wave.append(b,()->false);wave.checkpoint();wave.finish(new WavInfo("Retomada","Livro","Autor",1));}byte[] data=Files.readAllBytes(partial.toPath());ok(Arrays.equals(new byte[]{1,0,2,0},Arrays.copyOfRange(data,44,48)),"resumed audio has no missing or repeated chunk");ok(WaveJoiner.inspect(partial).length==4,"resumed PCM remains a valid WAV");
 File large=root.resolve("long.wav").toFile();long hour=24000L*2*3601;try(RandomAccessFile sparse=new RandomAccessFile(large,"rw")){sparse.setLength(44+hour);}try(CheckpointWave wave=new CheckpointWave(large,hour,1,1,24000,16)){wave.append(a,()->false);wave.checkpoint();ok(wave.bytes>WaveJoiner.MAX_BYTES&&wave.bytes==hour+2,"single output accepts more than one hour and more than 128 MB");}try(RandomAccessFile in=new RandomAccessFile(large,"r")){in.seek(40);ok(Integer.toUnsignedLong(Integer.reverseBytes(in.readInt()))==hour+2,"large WAV uses correct unsigned data length");}large.delete();
 File bg=root.resolve("bg.pcm").toFile();try(FileOutputStream out=new FileOutputStream(bg)){for(int n=0;n<24000;n++){int value=4000;out.write(value&255);out.write(value>>8);}}byte[] samples=new byte[800];for(int n=0;n<samples.length;n+=2){samples[n]=(byte)0xe8;samples[n+1]=3;}File voice=root.resolve("voice.wav").toFile();WaveJoinerTest.wav(voice,24000,1,16,samples);File mute=root.resolve("mute.wav").toFile(),mix=root.resolve("mix.wav").toFile();BackgroundMixer.mix(voice,mute,bg,24000,1,1000,0,()->false);BackgroundMixer.mix(voice,mix,bg,24000,1,1000,25,()->false);ok(Arrays.equals(samples,Arrays.copyOfRange(Files.readAllBytes(mute.toPath()),44,844)),"background volume zero preserves voice bytes exactly");byte[] mixed=Files.readAllBytes(mix.toPath());ok((short)((mixed[44]&255)|(mixed[45]<<8))==2000,"background gain adds only the selected music volume");ok(WaveJoiner.inspect(mix).rate==24000&&WaveJoiner.inspect(mix).bits==16,"mix preserves voice PCM format");
 File first=root.resolve("first.wav").toFile(),second=root.resolve("second.wav").toFile(),m1=root.resolve("m1.wav").toFile(),m2=root.resolve("m2.wav").toFile();WaveJoinerTest.wav(first,24000,1,16,Arrays.copyOfRange(samples,0,400));WaveJoinerTest.wav(second,24000,1,16,Arrays.copyOfRange(samples,400,800));BackgroundMixer.mix(first,m1,bg,24000,1,1000,25,()->false);BackgroundMixer.mix(second,m2,bg,24000,1,1200,25,()->false);byte[] joined=new byte[800];System.arraycopy(Files.readAllBytes(m1.toPath()),44,joined,0,400);System.arraycopy(Files.readAllBytes(m2.toPath()),44,joined,400,400);ok(Arrays.equals(joined,Arrays.copyOfRange(mixed,44,844)),"background alignment is continuous across generated chunks");
 File resampled=root.resolve("resampled.wav").toFile();BackgroundMixer.mix(voice,resampled,bg,48000,1,12000,30,()->false);ok(WaveJoiner.inspect(resampled).length==samples.length,"resampling background never changes voice duration");
 File decoded=root.resolve("decoded.pcm").toFile();WaveJoiner.Format decodedFormat=BackgroundWave.decode(voice,decoded,()->false);ok(decodedFormat.rate==24000&&Arrays.equals(samples,Files.readAllBytes(decoded.toPath())),"WAV background decoding works without a device codec and preserves PCM16");
 System.out.println("PASS "+checks+" durable large WAV and background mixing checks");}
}
